@inject MyNotionDataProvider DataProvider
@inject MyNotionBlockProvider BlockProvider
@inject MyTokenProvider TokenProvider

<TmNotionEditor DataProvider="@DataProvider"
                BlockProvider="@BlockProvider"
                TokenProvider="@TokenProvider"
                InitialPageId="my-page-id"
                Class="h-full" />

@using Tempo.Blazor.NotionEditor.Enums

@code {
    private static readonly IReadOnlySet<BlockType> AllowedTypes = new HashSet<BlockType>
    {
        BlockType.Paragraph,
        BlockType.Heading1,
        BlockType.Heading2,
        BlockType.BulletList,
        BlockType.NumberedList,
        BlockType.TodoItem,
    };
}

<TmNotionEditor DataProvider="@DataProvider"
                BlockProvider="@BlockProvider"
                AllowedBlockTypes="@AllowedTypes"
                InitialPageId="@_pageId" />
